/** Fixed signed application proofs qualify all supplied cuts on the next actual common input. */
public final class ContextUniversalSignedFixedApplicationRoundsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits limits(int fact){return new ContextUniversalFrozenBranch.Limits(16,16,fact,512,256,WORK,500000,65536);}
    static Result run(Snapshot x,List<Snapshot> foreign,Packet p,Map<Cut,PrivatePool> pools,Exchange symbolic,int fact,int rounds){return ContextUniversalSignedUnitRounds.runFixedApplications(x,foreign,p,pools,symbolic,limits(fact),rounds,WORK);}
    static void incomplete(Result r,String phase,int completed,String why){require(r.status==Status.INCOMPLETE&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&r.refutations.isEmpty()&&r.phase.equals(phase)&&r.completedRounds==completed,why+": "+r.phase+" "+r.reason);}
    static Result stable(Result r,Exchange initial){require(r.status==Status.STABLE_UNIT_POOLS&&r.output!=null&&r.symbolicOutput!=null&&r.history.size()==r.completedRounds&&r.refutations.isEmpty(),r.phase+" "+r.reason);Packet p=r.input;Exchange e=initial;Map<Cut,PrivatePool> pools=null;for(Round n:r.history){require(n.input==p&&n.symbolicInput==e,"actual preceding fixed/symbolic input");for(Cut cut:n.checks.keySet()){org.kanger.ContextUniversalFrozenConstraints.Result c=n.checks.get(cut);require(c.closed&&c.applications&&c.signedApplications&&!c.xRefuted&&!c.foreignRefuted&&c.common==p&&c.exchange==e&&c.pool==n.privateInput.get(cut),"every supplied cut/round uses exact fixed-signed frame");require(n.products.get(cut).bound&&n.products.get(cut).coverage==c&&n.barrier.branches.get(cut).proof==c&&n.symbolicOutput.checks.get(cut)==c,"all products and both barriers owned by identical checked ledgers");ContextUniversalFrozenConstraints.check(c,16,()->{});}if(pools!=null)for(Cut cut:pools.keySet())require(n.privateInput.get(cut)==pools.get(cut),"actual rebased private continuation");require(n.symbolicOutput.common==n.barrier.packet&&n.symbolicOutput.barrier==n.barrier,"exact actual fixed/symbolic rebase");p=n.barrier.packet;e=n.symbolicOutput;pools=n.barrier.privatePools;}Round last=r.history.get(r.history.size()-1);require(!last.commonChanged&&!last.privateChanged&&!last.symbolicChanged&&!last.barrier.localChanged,"full signed Source/minimum pools unchanged");return r;}
    static void refuted(Result r,int round,String why){require(r.status==Status.REFUTED&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&!r.refutations.isEmpty()&&r.completedRounds==round-1,why+": "+r.phase+" "+r.reason);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Refutation f:r.refutations.values()){require(f.round==round&&!f.proofs.isEmpty(),"actual next-input rejection receipt");for(Proof p:f.proofs){require(p.clause==null,"only empty rejection DAGs");ContextUniversalSignedFixedApplicationsRunner.audit(p,seen);}}}
    static Item item(Packet p,String name,boolean positive){return p.items.stream().filter(i->i.atom.predicate.equals(name)&&i.atom.positive==positive).findFirst().get();}
    static void baselineAndMinima()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w left(w)&&right(w)->p(w);"),a=bind(false,"!right(1); !~p(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> targets=Collections.singletonList(a);
        incomplete(ContextUniversalSignedUnitRounds.run(x,targets,p,Collections.emptyMap(),null,limits(1),8,WORK),"transfers",0,"old binary entry keeps negative2 scope");incomplete(ContextUniversalSignedUnitRounds.runApplications(x,targets,p,Collections.emptyMap(),null,limits(1),8,WORK),"transfers",0,"old positive-only entry keeps negative2 scope");
        Result r=stable(run(x,targets,p,Collections.emptyMap(),null,1,8),null);require(r.completedRounds==2&&item(r.output.packet,"left",false).proofs.stream().allMatch(s->s.depth==1&&s.sources.size()==3),"negative1 survives self/foreign next-input qualification at fact1");require(r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("right")||i.atom.predicate.equals("p")),"raw signed foreign premises not shared");require(stable(run(x,targets,r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"final actual common input stable1");
        incomplete(run(x,targets,p,Collections.emptyMap(),null,1,1),"round-limit",1,"first negative candidate cannot escape qualification");incomplete(run(x,targets,p,Collections.emptyMap(),null,0,8),"transfers",0,"bound0 refusal no prefix");
        Result old=ContextUniversalSignedUnitRounds.runApplications(x,targets,p,Collections.emptyMap(),null,limits(16),8,WORK);require(old.status==Status.STABLE_UNIT_POOLS&&item(old.output.packet,"left",false).proofs.stream().allMatch(s->s.depth==2),"actual old positive-mode stable negative2");Result improved=stable(run(x,targets,old.output.packet,old.output.privatePools,old.symbolicOutput,16,8),old.symbolicOutput);require(improved.history.get(0).commonChanged&&improved.history.get(0).input.items.size()==improved.history.get(0).barrier.packet.items.size()&&item(improved.output.packet,"left",false).proofs.stream().allMatch(s->s.depth==1),"same-Source grade-only improvement forces another barrier");require(item(old.output.packet,"left",false).proofs.stream().allMatch(s->s.depth==2),"old input immutable");
    }
    static void peersAndChains()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w left(w)&&right(w)->p(w);"),a=bind(false,"!right(1); !~p(1);"),b=bind(false,"!left(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Result r=run(x,order,p,Collections.emptyMap(),null,1,8);refuted(r,2,"peer positive opinion qualifies negative1 only next round");Refutation f=r.refutations.get(Cut.of(b));require(f!=null&&f.symbolicIdentity!=null&&!f.inputIdentity.equals(p.identity)&&f.proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"historical negative1 keeps exact empty2/four Sources");}
        Snapshot bridge=bind(false,"!guard(1); !@w guard(w)&&target(w)->left(w);"),opinion=bind(false,"!target(1);");Result chain=run(x,Arrays.asList(a,bridge,opinion),p,Collections.emptyMap(),null,2,8);refuted(chain,3,"negative donor application2 after barrier then peer rejection");require(chain.refutations.get(Cut.of(opinion)).proofs.stream().anyMatch(v->v.support.depth==3&&v.support.sources.size()==6),"negative chain empty3 preserves all six Sources");
        Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),WORK);Result direct=run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,1,8);refuted(direct,1,"same-cut signed application refutes before transfers");require(direct.refutations.get(Cut.of(group)).proofs.stream().anyMatch(v->v.support.depth==2&&(v.unit.producer!=null||v.horn.producer!=null)),"flattened direct rejection retains actual selected signed application");
        Snapshot unsupported=bind(false,"!bad(1)||other(1);");incomplete(run(x,Arrays.asList(group,unsupported),p,Collections.emptyMap(),null,16,8),"checks",0,"later unsupported cut suppresses earlier refutation prefix");
    }
    static void privateAndAlternatives()throws Exception {
        String seed="!$w p(w,1)&&q(w,1);";Snapshot x=bind(true,"!anchor(1); !@w p(w,1)&&q(w,1)->~r(w,1);"),a=bind(false,seed),b=bind(false,"!top(1); !@w s(w,1)&&top(1)->r(w,1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);Result r=stable(run(x,Arrays.asList(a,b),p,pools,null,2,8),null);Item s=item(r.output.packet,"s",false);Source binding=a.primary.get(0).source;require(s.atom.arguments.get(0).origin.source.equals(binding)&&s.proofs.stream().allMatch(v->v.depth==2&&v.sources.size()==4&&v.sources.contains(binding)),"physical private Origin/binding Source survives negative1 and negative donor application2");require(r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("p")||i.atom.predicate.equals("q")||i.atom.predicate.equals("top")),"raw private and independent premises stay local");require(pool.common==p&&pool.local.items.stream().noneMatch(i->i.atom.predicate.equals("r")||i.atom.predicate.equals("s")),"old private frame untouched");Result reverse=stable(run(x,Arrays.asList(b,a),p,pools,null,2,8),null);require(ContextWitnessResultTransport.sameContents(r.output.packet,reverse.output.packet,WORK),"reverse cuts preserve whole signed physical output");
        Snapshot positive=bind(false,"!@w r(w,1);");Result collision=run(x,Arrays.asList(a,positive),p,pools,null,1,8);refuted(collision,2,"private negative product qualifies independent universal positive next round");require(collision.refutations.get(Cut.of(positive)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==3&&v.support.sources.contains(binding)),"rejection preserves actual binding Source");
        Snapshot anchor=bind(true,"!anchor(1);"),own=bind(false,seed+"!@w p(w,1)&&q(w,1)->~r(w,1);");Packet cp=ContextPrivateWitnessPoolRunner.common(anchor);PrivatePool raw=ContextWitnessResultTransport.privatePool(cp,anchor,own,WORK);Result local=stable(run(anchor,Collections.singletonList(own),cp,Collections.singletonMap(raw.cut,raw),null,1,8),null);require(local.completedRounds==2&&!local.history.get(0).commonChanged&&local.history.get(0).privateChanged&&local.output.packet.items.size()==1&&item(local.output.privatePools.get(raw.cut).local,"r",false).proofs.stream().allMatch(v->v.depth==1),"private-only negative growth prevents common-stable early stop");
        Snapshot ax=bind(true,"!anchor(1); !@w left(w)&&right(w)->p(w);"),donors=bind(false,"!right(1); !~p(1);"),loop=bind(false,"!@w left(w)->left(w);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(donors,loop),WORK);Packet ap=ContextPrivateWitnessPoolRunner.common(ax);Result alts=stable(run(ax,Collections.singletonList(group),ap,Collections.emptyMap(),null,2,8),null);Item left=item(alts.output.packet,"left",false);require(left.proofs.size()==2&&left.proofs.stream().anyMatch(v->v.depth==1&&v.sources.size()==3)&&left.proofs.stream().anyMatch(v->v.depth==2&&v.sources.size()==4),"deeper Source superset preserved after every barrier");incomplete(run(ax,Collections.singletonList(group),ap,Collections.emptyMap(),null,1,8),"transfers",0,"different Source minimum cannot hide deeper alternative");
    }
    static void symbolicAndScope()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1); !@v top(v);"),a=bind(false,"!@w p(w)&&q(w)->~r(w); !@w @v ~r(w)&&top(v)->~s(w,v);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Result r=stable(run(x,Collections.singletonList(a),p,Collections.emptyMap(),null,2,8),null);require(r.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("s")&&!u.clause.literals.get(0).positive&&u.support.depth==2&&u.owner.signedApplications),"negative application-backed symbolic unit retains signed owning mode after rebase");Snapshot positive=bind(false,"!@w @v s(w,v);");Result collision=run(x,Arrays.asList(a,positive),p,Collections.emptyMap(),null,2,8);refuted(collision,2,"symbolic negative2 reaches positive opinion on next barrier");require(collision.refutations.get(Cut.of(positive)).proofs.stream().anyMatch(v->v.support.depth==3&&v.support.sources.size()==6),"symbolic empty3 retains selected negative recipe and all six Sources");
        incomplete(run(x,Collections.singletonList(a),ContextPrivateWitnessPoolRunner.common(x),Collections.emptyMap(),r.symbolicOutput,16,8),"preflight",0,"equal different common cannot replace actual symbolic basis");Result work=ContextUniversalSignedUnitRounds.runFixedApplications(x,Collections.singletonList(a),p,Collections.emptyMap(),null,limits(16),8,1);incomplete(work,"preflight",0,"work refusal not contradiction");
        Snapshot anchor=bind(true,"!anchor(1);"),yes=bind(false,"!p(1);"),no=bind(false,"!~p(1);");Result independent=stable(run(anchor,Arrays.asList(yes,no),ContextPrivateWitnessPoolRunner.common(anchor),Collections.emptyMap(),null,1,1),null);require(independent.output.packet.items.size()==1,"unrelated anchor never communalizes raw A/B opposite opinions");
        Map<Cut,Packet> packets=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())packets.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(r.history.get(r.history.size()-1).input,new ArrayList<>(packets.keySet()),WORK).finish(packets,WORK).status==FamilyStatus.INCOMPLETE,"stable fixed signed unit pools issue no family STEP/admission");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-fixed-application-rounds-").toString());baselineAndMinima();peersAndChains();privateAndAlternatives();symbolicAndScope();System.out.println("CONTEXT_UNIVERSAL_SIGNED_FIXED_APPLICATION_ROUNDS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
